CREATE TEMP TABLE guide_units AS SELECT * FROM jsonb_to_recordset('[{"seq":1,"code":"GUIDE2026JSS2T3ANGLES","slug":"angles-and-polygons","name":"Angles and Polygons","body":"# Angles and Polygons — JSS2, Third Term\n## Learning objectives\nDistinguish types of angles, solve angle problems, classify polygons and use angle-sum rules to explain answers.\n## Core ideas\nAn angle is the turn between two rays sharing a vertex. Acute angles are smaller than 90°, right angles are 90°, obtuse angles lie between 90° and 180°, straight angles are 180°, and reflex angles lie between 180° and 360°. Angles on a straight line add to 180°. Angles around a point add to 360°. Vertically opposite angles are equal.\nA polygon is a closed plane figure with straight sides: triangle (3), quadrilateral (4), pentagon (5), hexagon (6), octagon (8). A **regular** polygon has equal sides and equal interior angles.\n## Derivation\nDraw diagonals from one vertex of a convex polygon with n sides. It forms n−2 triangles; since each triangle''s interior angles total 180°, the polygon''s total interior angle is **(n−2)×180°**. For a regular polygon, divide by n to get a single interior angle. The sum of one exterior angle at each vertex of a convex polygon is **360°**; a regular n-gon has exterior angle **360°÷n**.\n## Worked examples\n**Example 1:** For a regular octagon, (8−2)×180° = 1080° total; each interior angle is 1080÷8 = **135°**; each exterior angle is 360÷8 = **45°**. Check 135+45=180.\n**Example 2:** On a straight line, if one angle is 67°, the other is 180−67=**113°**.\n**Example 3:** Around a point, if two angles are 95° and 110°, the third is 360−95−110=**155°**.\n## Construction\nUsing a ruler and protractor, draw a baseline, mark a vertex, align the protractor''s zero with the baseline and measure the required turn, for example 120°. Draw and label the second ray. For compass work, do not change radii when transferring equal arcs.\n## Visual recap\n| Sides | Polygon | Interior sum |\n|---:|---|---:|\n| 3 | Triangle | 180° |\n| 4 | Quadrilateral | 360° |\n| 5 | Pentagon | 540° |\n| 6 | Hexagon | 720° |\n| 8 | Octagon | 1080° |\n## Self-check\nFind the interior sum of a decagon (**1440°**), the exterior angle of a regular hexagon (**60°**), and the supplement of 72° (**108°**). Show a formula before substituting.\n## Mistakes to avoid\nNever confuse a polygon''s entire interior sum with one angle. Dividing the interior sum by n is valid only for a regular polygon. Label unknowns and verify degrees.","points":["Angles around a point total 360°.","Angles on a straight line total 180°.","Interior sum of an n-sided polygon = (n−2)×180°.","Each exterior angle of a regular n-gon = 360°÷n."],"cards":[{"front":"Interior angle sum of a polygon?","back":"(n−2)×180° for n sides.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Exterior angle of regular n-gon?","back":"360°÷n.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"How many degrees around a point?","back":"360°.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"How many degrees on a straight line?","back":"180°.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"When can each interior angle be calculated by dividing by n?","back":"Only for a regular polygon.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"What does regular mean?","back":"All side lengths equal and all interior angles equal.","sourceKind":"original-curriculum","difficulty":"medium"}],"questions":[{"question":"Calculate the interior angle sum of a 5-sided polygon.","options":[{"id":"A","text":"540°"},{"id":"B","text":"360°"},{"id":"C","text":"720°"},{"id":"D","text":"270°"}],"answer":"A","explanation":"Using (n−2)×180°, (5−2)×180°=540°."},{"question":"Calculate the interior angle sum of a 6-sided polygon.","options":[{"id":"A","text":"540°"},{"id":"B","text":"720°"},{"id":"C","text":"900°"},{"id":"D","text":"360°"}],"answer":"B","explanation":"Using (n−2)×180°, (6−2)×180°=720°."},{"question":"Calculate the interior angle sum of a 7-sided polygon.","options":[{"id":"A","text":"720°"},{"id":"B","text":"1080°"},{"id":"C","text":"900°"},{"id":"D","text":"450°"}],"answer":"C","explanation":"Using (n−2)×180°, (7−2)×180°=900°."},{"question":"Calculate the interior angle sum of a 8-sided polygon.","options":[{"id":"A","text":"900°"},{"id":"B","text":"1260°"},{"id":"C","text":"540°"},{"id":"D","text":"1080°"}],"answer":"D","explanation":"Using (n−2)×180°, (8−2)×180°=1080°."},{"question":"Calculate the interior angle sum of a 9-sided polygon.","options":[{"id":"A","text":"1260°"},{"id":"B","text":"1080°"},{"id":"C","text":"1440°"},{"id":"D","text":"630°"}],"answer":"A","explanation":"Using (n−2)×180°, (9−2)×180°=1260°."},{"question":"Calculate the interior angle sum of a 10-sided polygon.","options":[{"id":"A","text":"1260°"},{"id":"B","text":"1440°"},{"id":"C","text":"1620°"},{"id":"D","text":"720°"}],"answer":"B","explanation":"Using (n−2)×180°, (10−2)×180°=1440°."},{"question":"Calculate the interior angle sum of a 12-sided polygon.","options":[{"id":"A","text":"1620°"},{"id":"B","text":"1980°"},{"id":"C","text":"1800°"},{"id":"D","text":"900°"}],"answer":"C","explanation":"Using (n−2)×180°, (12−2)×180°=1800°."},{"question":"One exterior angle of a regular 4-sided polygon is:","options":[{"id":"A","text":"45°"},{"id":"B","text":"180°"},{"id":"C","text":"105°"},{"id":"D","text":"90°"}],"answer":"D","explanation":"All regular exterior angles total 360°. Divide by 4 to get 90°."},{"question":"One exterior angle of a regular 5-sided polygon is:","options":[{"id":"A","text":"72°"},{"id":"B","text":"36°"},{"id":"C","text":"144°"},{"id":"D","text":"87°"}],"answer":"A","explanation":"All regular exterior angles total 360°. Divide by 5 to get 72°."},{"question":"One exterior angle of a regular 6-sided polygon is:","options":[{"id":"A","text":"30°"},{"id":"B","text":"60°"},{"id":"C","text":"120°"},{"id":"D","text":"75°"}],"answer":"B","explanation":"All regular exterior angles total 360°. Divide by 6 to get 60°."},{"question":"One exterior angle of a regular 8-sided polygon is:","options":[{"id":"A","text":"22.5°"},{"id":"B","text":"90°"},{"id":"C","text":"45°"},{"id":"D","text":"60°"}],"answer":"C","explanation":"All regular exterior angles total 360°. Divide by 8 to get 45°."},{"question":"One exterior angle of a regular 9-sided polygon is:","options":[{"id":"A","text":"20°"},{"id":"B","text":"80°"},{"id":"C","text":"55°"},{"id":"D","text":"40°"}],"answer":"D","explanation":"All regular exterior angles total 360°. Divide by 9 to get 40°."},{"question":"One exterior angle of a regular 10-sided polygon is:","options":[{"id":"A","text":"36°"},{"id":"B","text":"18°"},{"id":"C","text":"72°"},{"id":"D","text":"51°"}],"answer":"A","explanation":"All regular exterior angles total 360°. Divide by 10 to get 36°."},{"question":"One exterior angle of a regular 12-sided polygon is:","options":[{"id":"A","text":"15°"},{"id":"B","text":"30°"},{"id":"C","text":"60°"},{"id":"D","text":"45°"}],"answer":"B","explanation":"All regular exterior angles total 360°. Divide by 12 to get 30°."},{"question":"Find one interior angle of a regular 4-sided polygon.","options":[{"id":"A","text":"45°"},{"id":"B","text":"110°"},{"id":"C","text":"90°"},{"id":"D","text":"70°"}],"answer":"C","explanation":"One exterior angle is 360÷4°; subtract from 180° to obtain 90°."},{"question":"Find one interior angle of a regular 5-sided polygon.","options":[{"id":"A","text":"54°"},{"id":"B","text":"128°"},{"id":"C","text":"88°"},{"id":"D","text":"108°"}],"answer":"D","explanation":"One exterior angle is 360÷5°; subtract from 180° to obtain 108°."},{"question":"Find one interior angle of a regular 6-sided polygon.","options":[{"id":"A","text":"120°"},{"id":"B","text":"60°"},{"id":"C","text":"140°"},{"id":"D","text":"100°"}],"answer":"A","explanation":"One exterior angle is 360÷6°; subtract from 180° to obtain 120°."},{"question":"Find one interior angle of a regular 8-sided polygon.","options":[{"id":"A","text":"67.5°"},{"id":"B","text":"135°"},{"id":"C","text":"155°"},{"id":"D","text":"115°"}],"answer":"B","explanation":"One exterior angle is 360÷8°; subtract from 180° to obtain 135°."},{"question":"Find one interior angle of a regular 10-sided polygon.","options":[{"id":"A","text":"72°"},{"id":"B","text":"164°"},{"id":"C","text":"144°"},{"id":"D","text":"124°"}],"answer":"C","explanation":"One exterior angle is 360÷10°; subtract from 180° to obtain 144°."},{"question":"Find one interior angle of a regular 12-sided polygon.","options":[{"id":"A","text":"75°"},{"id":"B","text":"170°"},{"id":"C","text":"130°"},{"id":"D","text":"150°"}],"answer":"D","explanation":"One exterior angle is 360÷12°; subtract from 180° to obtain 150°."},{"question":"Two angles on a straight line are 42° and x. Find x.","options":[{"id":"A","text":"138°"},{"id":"B","text":"42°"},{"id":"C","text":"222°"},{"id":"D","text":"318°"}],"answer":"A","explanation":"Supplementary angles total 180°, so x=180−42=138°."},{"question":"Two angles on a straight line are 57° and x. Find x.","options":[{"id":"A","text":"57°"},{"id":"B","text":"123°"},{"id":"C","text":"237°"},{"id":"D","text":"303°"}],"answer":"B","explanation":"Supplementary angles total 180°, so x=180−57=123°."},{"question":"Two angles on a straight line are 68° and x. Find x.","options":[{"id":"A","text":"68°"},{"id":"B","text":"248°"},{"id":"C","text":"112°"},{"id":"D","text":"292°"}],"answer":"C","explanation":"Supplementary angles total 180°, so x=180−68=112°."},{"question":"Two angles on a straight line are 83° and x. Find x.","options":[{"id":"A","text":"83°"},{"id":"B","text":"263°"},{"id":"C","text":"277°"},{"id":"D","text":"97°"}],"answer":"D","explanation":"Supplementary angles total 180°, so x=180−83=97°."}]},{"seq":2,"code":"GUIDE2026JSS2T3ELEV","slug":"angles-of-elevation-and-depression","name":"Angles of Elevation and Depression","body":"# Angles of Elevation and Depression — JSS2, Third Term\n## Learning objectives\nIdentify horizontal lines and sightlines, distinguish upward and downward angles, and solve right-triangle height-distance questions.\n## Observation\nAn **angle of elevation** is measured upward from a horizontal reference line to an object higher than the observer. An **angle of depression** is measured downward from the horizontal towards something lower. The reference is never the vertical wall. The line of sight goes straight from the observer to the viewed object.\n## Make a useful diagram\nDraw the ground as a horizontal line, the mast as a vertical line, and the sightline as a sloping line. The horizontal ground distance is the **adjacent** side, the height above the eye is the **opposite** side, and the sightline is the **hypotenuse** of a right triangle.\n## Calculation method\nThe right-triangle tangent relation is **tan θ = opposite ÷ adjacent**. Thus height above eye level = ground distance × tan θ. At 45°, tan 45°=1, meaning opposite and adjacent legs are equal.\n## Worked examples\n**Example 1:** A mast is viewed from 20 m away at elevation 45°. Its height above eye level is 20×1=**20 m**. If eye height is 1.5 m, height from the ground is **21.5 m**.\n**Example 2:** A car viewed from a platform 30 m above level ground at depression 45° is horizontally **30 m** away. Draw two parallel horizontal lines to see why the acute sightline angles match.\n**Example 3:** A plan uses 1 cm = 5 m. A horizontal drawing distance of 6 cm represents **30 m** in reality.\n## Scale drawing alternative\nIf your class has not yet studied tangent values formally, construct the specified angle carefully with a protractor at scale, draw the right triangle and measure the opposite leg using the drawing''s scale. Record expected measurement error.\n## Visual reference\n| Segment | Meaning |\n|---|---|\n| Horizontal leg | Ground distance |\n| Vertical leg | Height difference |\n| Sloping leg | Line of sight |\n| Angle from horizontal, upwards | Elevation |\n| Angle from horizontal, downwards | Depression |\n## Practise and check\nAt 45° and horizontal distance 12 m, height above eye level is **12 m**. If the eye is 1.6 m high, total object height is **13.6 m**.\n## Safety and common errors\nNever measure from a dangerous roof or beside live power lines. Keep metres and centimetres distinct, draw the angle from horizontal and add eye height only when asked for height from the ground.","points":["Elevation: upward from the horizontal.","Depression: downward from the horizontal.","tan θ = height above eye ÷ horizontal distance.","Object height may require adding eye height."],"cards":[{"front":"Angle of elevation?","back":"An upward angle measured from horizontal.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Angle of depression?","back":"A downward angle measured from horizontal.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"What is tan θ?","back":"Opposite side divided by adjacent side.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"At 45°, what is tan θ?","back":"1.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"What is the hypotenuse in a sightline problem?","back":"The sloping line of sight.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Why add eye height?","back":"To convert height above eye level to height from ground level.","sourceKind":"original-curriculum","difficulty":"medium"}],"questions":[{"question":"At elevation 45° and a horizontal distance of 8 m, what is height above eye level?","options":[{"id":"A","text":"8 m"},{"id":"B","text":"16 m"},{"id":"C","text":"4 m"},{"id":"D","text":"18 m"}],"answer":"A","explanation":"tan45°=1, so the height above eye level equals the 8 m ground distance."},{"question":"At elevation 45° and a horizontal distance of 12 m, what is height above eye level?","options":[{"id":"A","text":"24 m"},{"id":"B","text":"12 m"},{"id":"C","text":"6 m"},{"id":"D","text":"22 m"}],"answer":"B","explanation":"tan45°=1, so the height above eye level equals the 12 m ground distance."},{"question":"At elevation 45° and a horizontal distance of 15 m, what is height above eye level?","options":[{"id":"A","text":"30 m"},{"id":"B","text":"7.5 m"},{"id":"C","text":"15 m"},{"id":"D","text":"25 m"}],"answer":"C","explanation":"tan45°=1, so the height above eye level equals the 15 m ground distance."},{"question":"At elevation 45° and a horizontal distance of 18 m, what is height above eye level?","options":[{"id":"A","text":"36 m"},{"id":"B","text":"9 m"},{"id":"C","text":"28 m"},{"id":"D","text":"18 m"}],"answer":"D","explanation":"tan45°=1, so the height above eye level equals the 18 m ground distance."},{"question":"At elevation 45° and a horizontal distance of 20 m, what is height above eye level?","options":[{"id":"A","text":"20 m"},{"id":"B","text":"40 m"},{"id":"C","text":"10 m"},{"id":"D","text":"30 m"}],"answer":"A","explanation":"tan45°=1, so the height above eye level equals the 20 m ground distance."},{"question":"At elevation 45° and a horizontal distance of 24 m, what is height above eye level?","options":[{"id":"A","text":"48 m"},{"id":"B","text":"24 m"},{"id":"C","text":"12 m"},{"id":"D","text":"34 m"}],"answer":"B","explanation":"tan45°=1, so the height above eye level equals the 24 m ground distance."},{"question":"At elevation 45° and a horizontal distance of 30 m, what is height above eye level?","options":[{"id":"A","text":"60 m"},{"id":"B","text":"15 m"},{"id":"C","text":"30 m"},{"id":"D","text":"40 m"}],"answer":"C","explanation":"tan45°=1, so the height above eye level equals the 30 m ground distance."},{"question":"At elevation 45°, horizontal distance is 8 m and eye height is 1.5 m. What is total height?","options":[{"id":"A","text":"8 m"},{"id":"B","text":"11 m"},{"id":"C","text":"14 m"},{"id":"D","text":"9.5 m"}],"answer":"D","explanation":"Object height=8×tan45°+1.5=9.5 m."},{"question":"At elevation 45°, horizontal distance is 10 m and eye height is 1.5 m. What is total height?","options":[{"id":"A","text":"11.5 m"},{"id":"B","text":"10 m"},{"id":"C","text":"13 m"},{"id":"D","text":"16 m"}],"answer":"A","explanation":"Object height=10×tan45°+1.5=11.5 m."},{"question":"At elevation 45°, horizontal distance is 12 m and eye height is 1.5 m. What is total height?","options":[{"id":"A","text":"12 m"},{"id":"B","text":"13.5 m"},{"id":"C","text":"15 m"},{"id":"D","text":"18 m"}],"answer":"B","explanation":"Object height=12×tan45°+1.5=13.5 m."},{"question":"At elevation 45°, horizontal distance is 15 m and eye height is 1.5 m. What is total height?","options":[{"id":"A","text":"15 m"},{"id":"B","text":"18 m"},{"id":"C","text":"16.5 m"},{"id":"D","text":"21 m"}],"answer":"C","explanation":"Object height=15×tan45°+1.5=16.5 m."},{"question":"At elevation 45°, horizontal distance is 20 m and eye height is 1.5 m. What is total height?","options":[{"id":"A","text":"20 m"},{"id":"B","text":"23 m"},{"id":"C","text":"26 m"},{"id":"D","text":"21.5 m"}],"answer":"D","explanation":"Object height=20×tan45°+1.5=21.5 m."},{"question":"If tan θ=3/4, with horizontal distance 12 m, what is vertical rise?","options":[{"id":"A","text":"9 m"},{"id":"B","text":"12 m"},{"id":"C","text":"16 m"},{"id":"D","text":"Not enough information"}],"answer":"A","explanation":"Height=adjacent×tanθ=12×3/4=9 m."},{"question":"If tan θ=3/4, with horizontal distance 16 m, what is vertical rise?","options":[{"id":"A","text":"16 m"},{"id":"B","text":"12 m"},{"id":"C","text":"21.333333333333332 m"},{"id":"D","text":"20 m"}],"answer":"B","explanation":"Height=adjacent×tanθ=16×3/4=12 m."},{"question":"If tan θ=3/4, with horizontal distance 20 m, what is vertical rise?","options":[{"id":"A","text":"20 m"},{"id":"B","text":"26.666666666666668 m"},{"id":"C","text":"15 m"},{"id":"D","text":"24 m"}],"answer":"C","explanation":"Height=adjacent×tanθ=20×3/4=15 m."},{"question":"If tan θ=3/4, with horizontal distance 28 m, what is vertical rise?","options":[{"id":"A","text":"28 m"},{"id":"B","text":"37.333333333333336 m"},{"id":"C","text":"32 m"},{"id":"D","text":"21 m"}],"answer":"D","explanation":"Height=adjacent×tanθ=28×3/4=21 m."},{"question":"If tan θ=3/4, with horizontal distance 32 m, what is vertical rise?","options":[{"id":"A","text":"24 m"},{"id":"B","text":"32 m"},{"id":"C","text":"42.666666666666664 m"},{"id":"D","text":"36 m"}],"answer":"A","explanation":"Height=adjacent×tanθ=32×3/4=24 m."},{"question":"From which reference is the angle of depression measured?","options":[{"id":"A","text":"Vertical downwards"},{"id":"B","text":"Horizontal downwards"},{"id":"C","text":"Horizontal upwards"},{"id":"D","text":"Along the object height"}],"answer":"B","explanation":"The angle of depression is measured downwards from the observer''s horizontal line."},{"question":"What side is the line of sight in a height-distance right triangle?","options":[{"id":"A","text":"Opposite vertical height"},{"id":"B","text":"Adjacent horizontal length"},{"id":"C","text":"Hypotenuse"},{"id":"D","text":"The right angle"}],"answer":"C","explanation":"The sloping line of sight is opposite the right angle and is the hypotenuse."}]},{"seq":3,"code":"GUIDE2026JSS2T3BEAR1","slug":"bearings-and-distances-one","name":"Bearings and Distances I","body":"# Bearings and Distances I — JSS2, Third Term\n## Learning objectives\nRead the compass, express directions as three-figure bearings, reverse bearings, use map scales and distinguish travelled length from direct distance.\n## The convention\nA **bearing** is an angle measured **clockwise from North** at the location where movement starts. It is always written using three figures: 045°, 090° or 270°, for example. Start every diagram by drawing a North arrow at the correct point.\n## Cardinal and intercardinal bearings\nNorth = 000°; East = 090°; South = 180°; West = 270°. North-east = 045°, South-east = 135°, South-west = 225° and North-west = 315°. A direction N60°E gives 060°, while S40°W gives 220°.\n## Back bearings\nA back bearing points along the same line but in reverse. Add 180° to a forward bearing below 180°, or subtract 180° from one of 180° or more. For example, the reverse of 070° is **250°**, while the reverse of 225° is **045°**. Both answers must be written with three digits.\n## Distances from a diagram\nFor journeys at right angles, calculate direct distance with Pythagoras. A walker goes 6 km East then 8 km North. Path length = 6+8=**14 km**, but displacement length = √(6²+8²)=**10 km**. These are different quantities.\n## Map scale\nAt a scale of 1 cm to 2 km, 4.5 cm represents **9 km**. Convert using the ratio before drawing conclusions.\n## Worked direction example\nA boat moves on 120° from harbour A to B. The direction from B back to A is 120°+180°=**300°**. Draw the North line at B before making the return measurement.\n## Visual recap\n| North | East | South | West |\n|---:|---:|---:|---:|\n| 000° | 090° | 180° | 270° |\n| North-east | South-east | South-west | North-west |\n| 045° | 135° | 225° | 315° |\n## Self-test\nFind the reverse of 315° (**135°**) and the direct distance after 5 km North then 12 km East (**13 km**). If the diagram uses 1 cm = 3 km, a 5 cm separation is **15 km**.\n## Avoid\nDo not measure anticlockwise; do not omit the leading zero; do not apply a North arrow drawn at a different point; do not mistake path distance for displacement.","points":["Measure bearings clockwise from North.","Three-figure notation is required.","Back bearings differ by 180°.","Direct distance for perpendicular journeys uses Pythagoras."],"cards":[{"front":"Bearing of East?","back":"090°.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Bearing of South-west?","back":"225°.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Starting line for a bearing?","back":"North.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Direction of measurement?","back":"Clockwise.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Back bearing of 075°?","back":"255°.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Direct distance after 3 km East and 4 km North?","back":"5 km.","sourceKind":"original-curriculum","difficulty":"medium"}],"questions":[{"question":"The return bearing of 035° is:","options":[{"id":"A","text":"245°"},{"id":"B","text":"260°"},{"id":"C","text":"305°"},{"id":"D","text":"215°"}],"answer":"D","explanation":"Reverse the direction by 180°, giving 215°."},{"question":"The return bearing of 060° is:","options":[{"id":"A","text":"240°"},{"id":"B","text":"270°"},{"id":"C","text":"285°"},{"id":"D","text":"330°"}],"answer":"A","explanation":"Reverse the direction by 180°, giving 240°."},{"question":"The return bearing of 075° is:","options":[{"id":"A","text":"285°"},{"id":"B","text":"255°"},{"id":"C","text":"300°"},{"id":"D","text":"345°"}],"answer":"B","explanation":"Reverse the direction by 180°, giving 255°."},{"question":"The return bearing of 110° is:","options":[{"id":"A","text":"320°"},{"id":"B","text":"335°"},{"id":"C","text":"290°"},{"id":"D","text":"020°"}],"answer":"C","explanation":"Reverse the direction by 180°, giving 290°."},{"question":"The return bearing of 145° is:","options":[{"id":"A","text":"355°"},{"id":"B","text":"010°"},{"id":"C","text":"055°"},{"id":"D","text":"325°"}],"answer":"D","explanation":"Reverse the direction by 180°, giving 325°."},{"question":"The return bearing of 210° is:","options":[{"id":"A","text":"030°"},{"id":"B","text":"060°"},{"id":"C","text":"075°"},{"id":"D","text":"120°"}],"answer":"A","explanation":"Reverse the direction by 180°, giving 030°."},{"question":"The return bearing of 225° is:","options":[{"id":"A","text":"075°"},{"id":"B","text":"045°"},{"id":"C","text":"090°"},{"id":"D","text":"135°"}],"answer":"B","explanation":"Reverse the direction by 180°, giving 045°."},{"question":"The return bearing of 250° is:","options":[{"id":"A","text":"100°"},{"id":"B","text":"115°"},{"id":"C","text":"070°"},{"id":"D","text":"160°"}],"answer":"C","explanation":"Reverse the direction by 180°, giving 070°."},{"question":"The return bearing of 315° is:","options":[{"id":"A","text":"165°"},{"id":"B","text":"180°"},{"id":"C","text":"225°"},{"id":"D","text":"135°"}],"answer":"D","explanation":"Reverse the direction by 180°, giving 135°."},{"question":"Which bearing is East?","options":[{"id":"A","text":"090°"},{"id":"B","text":"135°"},{"id":"C","text":"180°"},{"id":"D","text":"270°"}],"answer":"A","explanation":"Measured clockwise from North, East is 090°."},{"question":"Which bearing is South?","options":[{"id":"A","text":"225°"},{"id":"B","text":"180°"},{"id":"C","text":"270°"},{"id":"D","text":"000°"}],"answer":"B","explanation":"Measured clockwise from North, South is 180°."},{"question":"Which bearing is West?","options":[{"id":"A","text":"315°"},{"id":"B","text":"000°"},{"id":"C","text":"270°"},{"id":"D","text":"090°"}],"answer":"C","explanation":"Measured clockwise from North, West is 270°."},{"question":"Which bearing is North-east?","options":[{"id":"A","text":"090°"},{"id":"B","text":"135°"},{"id":"C","text":"225°"},{"id":"D","text":"045°"}],"answer":"D","explanation":"Measured clockwise from North, North-east is 045°."},{"question":"Which bearing is South-east?","options":[{"id":"A","text":"135°"},{"id":"B","text":"180°"},{"id":"C","text":"225°"},{"id":"D","text":"315°"}],"answer":"A","explanation":"Measured clockwise from North, South-east is 135°."},{"question":"Which bearing is South-west?","options":[{"id":"A","text":"270°"},{"id":"B","text":"225°"},{"id":"C","text":"315°"},{"id":"D","text":"045°"}],"answer":"B","explanation":"Measured clockwise from North, South-west is 225°."},{"question":"Which bearing is North-west?","options":[{"id":"A","text":"000°"},{"id":"B","text":"045°"},{"id":"C","text":"315°"},{"id":"D","text":"135°"}],"answer":"C","explanation":"Measured clockwise from North, North-west is 315°."},{"question":"A person walks 3 km east then 4 km north. Find direct displacement length.","options":[{"id":"A","text":"7 km"},{"id":"B","text":"4 km"},{"id":"C","text":"Not enough information"},{"id":"D","text":"5 km"}],"answer":"D","explanation":"The route forms perpendicular legs. Distance=√(3²+4²)=5 km."},{"question":"A person walks 6 km east then 8 km north. Find direct displacement length.","options":[{"id":"A","text":"10 km"},{"id":"B","text":"14 km"},{"id":"C","text":"12 km"},{"id":"D","text":"9 km"}],"answer":"A","explanation":"The route forms perpendicular legs. Distance=√(6²+8²)=10 km."},{"question":"A person walks 5 km east then 12 km north. Find direct displacement length.","options":[{"id":"A","text":"17 km"},{"id":"B","text":"13 km"},{"id":"C","text":"15 km"},{"id":"D","text":"12 km"}],"answer":"B","explanation":"The route forms perpendicular legs. Distance=√(5²+12²)=13 km."},{"question":"A person walks 8 km east then 15 km north. Find direct displacement length.","options":[{"id":"A","text":"23 km"},{"id":"B","text":"19 km"},{"id":"C","text":"17 km"},{"id":"D","text":"16 km"}],"answer":"C","explanation":"The route forms perpendicular legs. Distance=√(8²+15²)=17 km."}]},{"seq":4,"code":"GUIDE2026JSS2T3BEAR2","slug":"bearings-and-distances-two","name":"Bearings and Distances II: Triangle Constructions","body":"# Bearings and Distances II: Triangle Constructions — JSS2, Third Term\n## Learning objectives\nConstruct triangles accurately using SSS, SAS and ASA data; bisect an angle with compass arcs; reject impossible measurements.\n## Why construction matters\nMeasured drawings support bearings and distance problems. A proper construction uses a ruler, sharp pencil, compass and protractor rather than guessing by eye. Keep light construction arcs as evidence of the method.\n## SSS: three given sides\nTo construct ABC with AB = 6 cm, AC = 5 cm and BC = 4 cm, draw AB=6 cm. Draw a radius-5 cm arc from A and a radius-4 cm arc from B. Mark an arc intersection C, then join AC and BC. Verify the lengths.\nThe **triangle inequality** requires the sum of any two side lengths to exceed the third. A triangle with sides 2, 3 and 6 cm is impossible because 2+3 is less than 6.\n## SAS: two sides and the included angle\nGiven AB=5 cm, AC=4 cm and angle BAC=60°, draw AB first. Construct a 60° ray at A, mark C at 4 cm on that ray, then join B to C. The given angle must be the angle **between** the two given sides.\n## ASA: two angles and their included side\nGiven AB=7 cm, angle A=45° and angle B=60°, draw AB. Construct rays at 45° and 60° on the same side of the line. Their intersection is C. The remaining angle equals **180°−45°−60°=75°**.\n## Angle bisectors\nTo bisect angle ABC, use B as compass centre to draw an arc meeting BA and BC at P and Q. Without changing the radius, draw matching arcs from P and Q to intersect at R. The ray BR is the bisector; if ABC was 80°, the two new angles are **40°** each.\n## Constructions with scale\nAt 1 cm = 3 m, a drawing length 5 cm is **15 m** in reality. Use the scale consistently for every side.\n## Quick table\n| Information supplied | Method |\n|---|---|\n| Three sides | SSS |\n| Two sides plus included angle | SAS |\n| Two angles plus included side | ASA |\n| Divide an angle equally | Angle bisector |\n## Independent work\nConstruct a 5-6-7 cm SSS triangle, followed by a 5-4 cm SAS triangle including 60°. Measure completed sides; explain why lengths 2, 4 and 7 cm cannot form a triangle. With angles 50° and 60°, the missing triangle angle is **70°**.\n## Avoid\nDo not alter compass width while bisecting. Do not treat a non-included angle as SAS, use thick freehand arcs, or claim an impossible set of side lengths is constructible.","points":["SSS gives three side lengths.","SAS gives two sides and their included angle.","ASA gives two angles and included side.","The sum of the two shorter sides must exceed the longest side."],"cards":[{"front":"What does SSS mean?","back":"Three given sides.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"SAS stands for?","back":"Two given sides with included angle.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"ASA stands for?","back":"Two angles with the side between them.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"When can three lengths make a triangle?","back":"When each pair''s sum is greater than the third length.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"What is an angle bisector?","back":"A line or ray that splits an angle in two equal parts.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Best tool for equal-radius arcs?","back":"A compass.","sourceKind":"original-curriculum","difficulty":"medium"}],"questions":[{"question":"Can side lengths 3 cm, 4 cm and 5 cm form a triangle?","options":[{"id":"A","text":"No"},{"id":"B","text":"Only if all angles are 90°"},{"id":"C","text":"Only with a larger protractor"},{"id":"D","text":"Yes"}],"answer":"D","explanation":"Use the triangle inequality: 3+4=7, which is greater than 5; therefore possible."},{"question":"Can side lengths 4 cm, 5 cm and 7 cm form a triangle?","options":[{"id":"A","text":"Yes"},{"id":"B","text":"No"},{"id":"C","text":"Only if all angles are 90°"},{"id":"D","text":"Only with a larger protractor"}],"answer":"A","explanation":"Use the triangle inequality: 4+5=9, which is greater than 7; therefore possible."},{"question":"Can side lengths 6 cm, 7 cm and 8 cm form a triangle?","options":[{"id":"A","text":"No"},{"id":"B","text":"Yes"},{"id":"C","text":"Only if all angles are 90°"},{"id":"D","text":"Only with a larger protractor"}],"answer":"B","explanation":"Use the triangle inequality: 6+7=13, which is greater than 8; therefore possible."},{"question":"Can side lengths 2 cm, 3 cm and 6 cm form a triangle?","options":[{"id":"A","text":"Yes"},{"id":"B","text":"Only if all angles are 90°"},{"id":"C","text":"No"},{"id":"D","text":"Only with a larger protractor"}],"answer":"C","explanation":"Use the triangle inequality: 2+3=5, which is not greater than 6; therefore impossible."},{"question":"Can side lengths 2 cm, 4 cm and 7 cm form a triangle?","options":[{"id":"A","text":"Yes"},{"id":"B","text":"Only if all angles are 90°"},{"id":"C","text":"Only with a larger protractor"},{"id":"D","text":"No"}],"answer":"D","explanation":"Use the triangle inequality: 2+4=6, which is not greater than 7; therefore impossible."},{"question":"Can side lengths 1 cm, 2 cm and 4 cm form a triangle?","options":[{"id":"A","text":"No"},{"id":"B","text":"Yes"},{"id":"C","text":"Only if all angles are 90°"},{"id":"D","text":"Only with a larger protractor"}],"answer":"A","explanation":"Use the triangle inequality: 1+2=3, which is not greater than 4; therefore impossible."},{"question":"Can side lengths 5 cm, 6 cm and 10 cm form a triangle?","options":[{"id":"A","text":"No"},{"id":"B","text":"Yes"},{"id":"C","text":"Only if all angles are 90°"},{"id":"D","text":"Only with a larger protractor"}],"answer":"B","explanation":"Use the triangle inequality: 5+6=11, which is greater than 10; therefore possible."},{"question":"Can side lengths 3 cm, 5 cm and 9 cm form a triangle?","options":[{"id":"A","text":"Yes"},{"id":"B","text":"Only if all angles are 90°"},{"id":"C","text":"No"},{"id":"D","text":"Only with a larger protractor"}],"answer":"C","explanation":"Use the triangle inequality: 3+5=8, which is not greater than 9; therefore impossible."},{"question":"An angle of 40° is bisected. Find one half.","options":[{"id":"A","text":"40°"},{"id":"B","text":"30°"},{"id":"C","text":"Not enough information"},{"id":"D","text":"20°"}],"answer":"D","explanation":"A bisector divides the original angle equally: 40÷2=20°."},{"question":"An angle of 60° is bisected. Find one half.","options":[{"id":"A","text":"30°"},{"id":"B","text":"60°"},{"id":"C","text":"40°"},{"id":"D","text":"50°"}],"answer":"A","explanation":"A bisector divides the original angle equally: 60÷2=30°."},{"question":"An angle of 70° is bisected. Find one half.","options":[{"id":"A","text":"70°"},{"id":"B","text":"35°"},{"id":"C","text":"45°"},{"id":"D","text":"55°"}],"answer":"B","explanation":"A bisector divides the original angle equally: 70÷2=35°."},{"question":"An angle of 80° is bisected. Find one half.","options":[{"id":"A","text":"80°"},{"id":"B","text":"50°"},{"id":"C","text":"40°"},{"id":"D","text":"60°"}],"answer":"C","explanation":"A bisector divides the original angle equally: 80÷2=40°."},{"question":"An angle of 100° is bisected. Find one half.","options":[{"id":"A","text":"100°"},{"id":"B","text":"60°"},{"id":"C","text":"70°"},{"id":"D","text":"50°"}],"answer":"D","explanation":"A bisector divides the original angle equally: 100÷2=50°."},{"question":"An angle of 120° is bisected. Find one half.","options":[{"id":"A","text":"60°"},{"id":"B","text":"120°"},{"id":"C","text":"70°"},{"id":"D","text":"80°"}],"answer":"A","explanation":"A bisector divides the original angle equally: 120÷2=60°."},{"question":"Two angles in a triangle are 45° and 60°. What is the third?","options":[{"id":"A","text":"105°"},{"id":"B","text":"75°"},{"id":"C","text":"85°"},{"id":"D","text":"65°"}],"answer":"B","explanation":"Triangle interior angles total 180°, so 180−45−60=75°."},{"question":"Two angles in a triangle are 40° and 70°. What is the third?","options":[{"id":"A","text":"110°"},{"id":"B","text":"80°"},{"id":"C","text":"70°"},{"id":"D","text":"60°"}],"answer":"C","explanation":"Triangle interior angles total 180°, so 180−40−70=70°."},{"question":"Two angles in a triangle are 50° and 60°. What is the third?","options":[{"id":"A","text":"110°"},{"id":"B","text":"80°"},{"id":"C","text":"60°"},{"id":"D","text":"70°"}],"answer":"D","explanation":"Triangle interior angles total 180°, so 180−50−60=70°."},{"question":"Two angles in a triangle are 30° and 80°. What is the third?","options":[{"id":"A","text":"70°"},{"id":"B","text":"110°"},{"id":"C","text":"80°"},{"id":"D","text":"60°"}],"answer":"A","explanation":"Triangle interior angles total 180°, so 180−30−80=70°."},{"question":"Two angles in a triangle are 65° and 45°. What is the third?","options":[{"id":"A","text":"110°"},{"id":"B","text":"70°"},{"id":"C","text":"80°"},{"id":"D","text":"60°"}],"answer":"B","explanation":"Triangle interior angles total 180°, so 180−65−45=70°."},{"question":"Two angles in a triangle are 55° and 50°. What is the third?","options":[{"id":"A","text":"105°"},{"id":"B","text":"85°"},{"id":"C","text":"75°"},{"id":"D","text":"65°"}],"answer":"C","explanation":"Triangle interior angles total 180°, so 180−55−50=75°."},{"question":"Which measurements are needed for an SAS triangle?","options":[{"id":"A","text":"Three side lengths"},{"id":"B","text":"Three angles"},{"id":"C","text":"Any two sides and any angle"},{"id":"D","text":"Two sides with the included angle"}],"answer":"D","explanation":"SAS means side-angle-side, with the angle included between both known sides."}]},{"seq":5,"code":"GUIDE2026JSS2T3STATS1","slug":"statistics-one-data-presentation","name":"Statistics I: Data Presentation","body":"# Statistics I: Data Presentation — JSS2, Third Term\n## Learning objectives\nCollect numerical data, make tally and frequency tables, and calculate useful summaries including mean, median, mode and range.\n## Why we collect data\nStatistics helps us summarise classroom measurements, market records and daily observations. **Raw data** is an unorganised list, and a **frequency** counts how often a value appears. A tally uses marks to count observations, grouping each fifth mark across four marks.\n## Example: borrowing books\nFive learners borrowed 1, 2, 2, 3 and 5 books. Organise the values:\n| Books | Tally | Frequency |\n|---:|---|---:|\n| 1 | I | 1 |\n| 2 | II | 2 |\n| 3 | I | 1 |\n| 5 | I | 1 |\n| Total | | 5 |\nAlways check that the total frequency equals the number of raw observations.\n## Measures of central tendency\nThe **mean** is the total divided by the count: (1+2+2+3+5)÷5 = **13÷5=2.6**. The **median** is the middle observation after sorting: **2**. The **mode** is the most frequently occurring observation: **2**. The **range** is maximum minus minimum: 5−1=**4**.\n## Even counts\nFor ordered values 2, 4, 6, 10 the median is the average of the two central values, (4+6)÷2 = **5**. Some datasets have two modes and some have no mode; avoid guessing based on the largest number.\n## Frequency-weighted average\nValues 2, 3 and 4 with frequencies 1, 2 and 3 have weighted sum (2×1)+(3×2)+(4×3)=20. Total frequency is 6, so mean≈**3.33**, not 20÷3. Multiply each value by its own frequency before dividing.\n## Visual summary\n| Measure | Rule |\n|---|---|\n| Mean | Total ÷ number of observations |\n| Median | Middle after arranging values |\n| Mode | Most frequent value |\n| Range | Largest − smallest |\n## Try independently\nFor 3,3,4,5,10, find mean (**5**), median (**4**), mode (**3**) and range (**7**). Make a tally table and verify its sum.\n## Reliable collection\nUse clear questions and consistent units, record sample size and keep learners'' personal data private. Do not invent responses to complete a table.\n## Common errors\nForgetting to sort before finding the median, dividing by the number of unique values, omitting zeros, or naming the largest value as the mode when it appears once.","points":["Frequency is how often a value occurs.","Mean = sum ÷ count.","Median is found after sorting.","Mode is most common.","Range = maximum − minimum."],"cards":[{"front":"What is a frequency?","back":"Number of times a value occurs.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Mean formula?","back":"Sum of values divided by number of observations.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Median of an even number of observations?","back":"Average of the two middle ordered values.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Mode?","back":"Most frequent value or values.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Range?","back":"Largest minus smallest.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"What should frequency counts total?","back":"The number of observations.","sourceKind":"original-curriculum","difficulty":"medium"}],"questions":[{"question":"Find the mean of 2, 4, 6, 8.","options":[{"id":"A","text":"5"},{"id":"B","text":"6"},{"id":"C","text":"4"},{"id":"D","text":"20"}],"answer":"A","explanation":"Sum=20. Divide by 4 observations to obtain mean=5."},{"question":"Find the mean of 3, 5, 7, 9.","options":[{"id":"A","text":"7"},{"id":"B","text":"6"},{"id":"C","text":"5"},{"id":"D","text":"24"}],"answer":"B","explanation":"Sum=24. Divide by 4 observations to obtain mean=6."},{"question":"Find the mean of 1, 2, 2, 3.","options":[{"id":"A","text":"3"},{"id":"B","text":"1"},{"id":"C","text":"2"},{"id":"D","text":"8"}],"answer":"C","explanation":"Sum=8. Divide by 4 observations to obtain mean=2."},{"question":"Find the mean of 4, 4, 5, 7.","options":[{"id":"A","text":"6"},{"id":"B","text":"4"},{"id":"C","text":"20"},{"id":"D","text":"5"}],"answer":"D","explanation":"Sum=20. Divide by 4 observations to obtain mean=5."},{"question":"Find the mean of 2, 2, 5, 7.","options":[{"id":"A","text":"4"},{"id":"B","text":"5"},{"id":"C","text":"3"},{"id":"D","text":"16"}],"answer":"A","explanation":"Sum=16. Divide by 4 observations to obtain mean=4."},{"question":"Find the mean of 10, 12, 14, 16.","options":[{"id":"A","text":"14"},{"id":"B","text":"13"},{"id":"C","text":"12"},{"id":"D","text":"52"}],"answer":"B","explanation":"Sum=52. Divide by 4 observations to obtain mean=13."},{"question":"What is the mode of 1, 3, 3, 5, 7?","options":[{"id":"A","text":"2"},{"id":"B","text":"4"},{"id":"C","text":"3"},{"id":"D","text":"5"}],"answer":"C","explanation":"The mode is the most frequent value: 3 appears twice and each other value once."},{"question":"What is the mode of 2, 2, 4, 6, 8?","options":[{"id":"A","text":"1"},{"id":"B","text":"3"},{"id":"C","text":"4"},{"id":"D","text":"2"}],"answer":"D","explanation":"The mode is the most frequent value: 2 appears twice and each other value once."},{"question":"What is the mode of 3, 4, 4, 5, 9?","options":[{"id":"A","text":"4"},{"id":"B","text":"3"},{"id":"C","text":"5"},{"id":"D","text":"6"}],"answer":"A","explanation":"The mode is the most frequent value: 4 appears twice and each other value once."},{"question":"What is the mode of 5, 6, 6, 7, 8?","options":[{"id":"A","text":"5"},{"id":"B","text":"6"},{"id":"C","text":"7"},{"id":"D","text":"8"}],"answer":"B","explanation":"The mode is the most frequent value: 6 appears twice and each other value once."},{"question":"What is the mode of 2, 3, 5, 5, 6?","options":[{"id":"A","text":"4"},{"id":"B","text":"6"},{"id":"C","text":"5"},{"id":"D","text":"7"}],"answer":"C","explanation":"The mode is the most frequent value: 5 appears twice and each other value once."},{"question":"Find the median of ordered data 2, 4, 6, 10.","options":[{"id":"A","text":"4"},{"id":"B","text":"6"},{"id":"C","text":"7"},{"id":"D","text":"5"}],"answer":"D","explanation":"With four ordered values, average the middle two: (4+6)÷2=5."},{"question":"Find the median of ordered data 1, 3, 7, 9.","options":[{"id":"A","text":"5"},{"id":"B","text":"3"},{"id":"C","text":"7"},{"id":"D","text":"Not enough information"}],"answer":"A","explanation":"With four ordered values, average the middle two: (3+7)÷2=5."},{"question":"Find the median of ordered data 4, 6, 8, 14.","options":[{"id":"A","text":"6"},{"id":"B","text":"7"},{"id":"C","text":"8"},{"id":"D","text":"9"}],"answer":"B","explanation":"With four ordered values, average the middle two: (6+8)÷2=7."},{"question":"Find the median of ordered data 3, 5, 7, 11.","options":[{"id":"A","text":"5"},{"id":"B","text":"7"},{"id":"C","text":"6"},{"id":"D","text":"8"}],"answer":"C","explanation":"With four ordered values, average the middle two: (5+7)÷2=6."},{"question":"Find the median of ordered data 2, 6, 12, 20.","options":[{"id":"A","text":"6"},{"id":"B","text":"12"},{"id":"C","text":"11"},{"id":"D","text":"9"}],"answer":"D","explanation":"With four ordered values, average the middle two: (6+12)÷2=9."},{"question":"What is the range of 3, 7, 9, 16?","options":[{"id":"A","text":"13"},{"id":"B","text":"11"},{"id":"C","text":"15"},{"id":"D","text":"16"}],"answer":"A","explanation":"Range is the largest minus the smallest: 16−3=13."},{"question":"What is the range of 2, 6, 8, 12?","options":[{"id":"A","text":"8"},{"id":"B","text":"10"},{"id":"C","text":"12"},{"id":"D","text":"Not enough information"}],"answer":"B","explanation":"Range is the largest minus the smallest: 12−2=10."},{"question":"What is the range of 5, 9, 11, 20?","options":[{"id":"A","text":"13"},{"id":"B","text":"17"},{"id":"C","text":"15"},{"id":"D","text":"20"}],"answer":"C","explanation":"Range is the largest minus the smallest: 20−5=15."},{"question":"What is the range of 4, 8, 10, 18?","options":[{"id":"A","text":"12"},{"id":"B","text":"16"},{"id":"C","text":"18"},{"id":"D","text":"14"}],"answer":"D","explanation":"Range is the largest minus the smallest: 18−4=14."},{"question":"What is the range of 1, 6, 12, 21?","options":[{"id":"A","text":"20"},{"id":"B","text":"18"},{"id":"C","text":"22"},{"id":"D","text":"21"}],"answer":"A","explanation":"Range is the largest minus the smallest: 21−1=20."}]},{"seq":6,"code":"GUIDE2026JSS2T3STATS2","slug":"statistics-two-graphical-representation","name":"Statistics II: Graphical Representation","body":"# Statistics II: Graphical Representation — JSS2, Third Term\n## Learning objectives\nRepresent collected frequencies in bar charts and pie charts, convert observations to percentages, and recognise misleading graph scales.\n## Bar charts\nBar charts compare distinct categories. Use category labels on one axis and a consistent numerical scale on the other; bars should have equal width. Suppose 24 learners choose Football 12, Volleyball 8, and Athletics 4. Use ticks 0,2,4,6,8,10,12 and bars of heights 12,8,4. Write the title *Preferred sports among 24 learners* and label the numerical axis *Number of learners*. Do not make the tallest bar wider merely because it is higher.\n## Pie charts\nOne full circle is 360°. A category''s sector angle is **frequency ÷ total frequency × 360°**. For the survey:\n- Football: 12÷24×360 = **180°**.\n- Volleyball: 8÷24×360 = **120°**.\n- Athletics: 4÷24×360 = **60°**.\nCheck the sector angles total 360°. Use a protractor to draw each central angle, colour or label each sector and show a legend where needed.\n## Percentages\nCategory percentage = frequency÷total×100%. Volleyball has 8 of 24 responses, so it represents **33⅓%**; a category with 25% of the responses has a sector of **90°**. Round fractions only at the end and disclose rounding if percentages no longer total exactly 100.\n## A second example\nA reading club has Science 15, Fiction 10, History 5 (total 30). Its pie-sector angles are **180°**, **120°** and **60°**. Science is half the whole group, not half the other categories individually.\n## Read graphs critically\nAlways inspect the graph title, axis unit, total sample and tick marks. A vertical axis starting at 90 rather than 0 exaggerates small variations. A pie chart that omits categories misrepresents the whole. A graph can display a relationship without proving causation.\n## Quick comparison\n| Display | What it communicates | Check |\n|---|---|---|\n| Frequency table | Exact counts | Frequencies total correctly |\n| Bar chart | Size comparison | Shared numerical scale |\n| Pie chart | Shares of a whole | 360° total |\n## Practise\nIf Red=10, Blue=5 and Green=5 out of 20, the pie angles are **180°,90°,90°**. Explain why equal frequencies have equal sector angles. Draw a matching bar chart and label its axes.\n## Common errors\nUsing 100° as a circle, omitting the total frequency in a sector calculation, inconsistent bar widths, or drawing a graph without stating the population and units.","points":["Pie-chart angle = category frequency÷total×360°.","Percent = category frequency÷total×100%.","Full pie chart = 360°.","Bar charts need consistent numerical scales."],"cards":[{"front":"Pie-chart angle formula?","back":"(Frequency÷total)×360°.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"What is the total angle in a pie chart?","back":"360°.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"Category percentage formula?","back":"(Frequency÷total)×100%.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"What is 25% as a pie-chart angle?","back":"90°.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"What is the key requirement for a bar chart scale?","back":"A consistent, labelled numerical axis.","sourceKind":"original-curriculum","difficulty":"medium"},{"front":"What should a graph title identify?","back":"What is measured and the group represented.","sourceKind":"original-curriculum","difficulty":"medium"}],"questions":[{"question":"Find the pie-chart sector angle for 4 of 20 responses.","options":[{"id":"A","text":"87°"},{"id":"B","text":"72°"},{"id":"C","text":"102°"},{"id":"D","text":"36°"}],"answer":"B","explanation":"Sector angle=(4/20)×360°=72°."},{"question":"Find the pie-chart sector angle for 6 of 24 responses.","options":[{"id":"A","text":"105°"},{"id":"B","text":"120°"},{"id":"C","text":"90°"},{"id":"D","text":"45°"}],"answer":"C","explanation":"Sector angle=(6/24)×360°=90°."},{"question":"Find the pie-chart sector angle for 8 of 24 responses.","options":[{"id":"A","text":"135°"},{"id":"B","text":"150°"},{"id":"C","text":"60°"},{"id":"D","text":"120°"}],"answer":"D","explanation":"Sector angle=(8/24)×360°=120°."},{"question":"Find the pie-chart sector angle for 12 of 24 responses.","options":[{"id":"A","text":"180°"},{"id":"B","text":"195°"},{"id":"C","text":"210°"},{"id":"D","text":"90°"}],"answer":"A","explanation":"Sector angle=(12/24)×360°=180°."},{"question":"Find the pie-chart sector angle for 5 of 20 responses.","options":[{"id":"A","text":"105°"},{"id":"B","text":"90°"},{"id":"C","text":"120°"},{"id":"D","text":"45°"}],"answer":"B","explanation":"Sector angle=(5/20)×360°=90°."},{"question":"Find the pie-chart sector angle for 10 of 40 responses.","options":[{"id":"A","text":"105°"},{"id":"B","text":"120°"},{"id":"C","text":"90°"},{"id":"D","text":"45°"}],"answer":"C","explanation":"Sector angle=(10/40)×360°=90°."},{"question":"Find the pie-chart sector angle for 3 of 15 responses.","options":[{"id":"A","text":"87°"},{"id":"B","text":"102°"},{"id":"C","text":"36°"},{"id":"D","text":"72°"}],"answer":"D","explanation":"Sector angle=(3/15)×360°=72°."},{"question":"Find the pie-chart sector angle for 9 of 30 responses.","options":[{"id":"A","text":"108°"},{"id":"B","text":"123°"},{"id":"C","text":"138°"},{"id":"D","text":"54°"}],"answer":"A","explanation":"Sector angle=(9/30)×360°=108°."},{"question":"What percentage is 5 of 20 learners?","options":[{"id":"A","text":"35%"},{"id":"B","text":"25%"},{"id":"C","text":"45%"},{"id":"D","text":"12.5%"}],"answer":"B","explanation":"Convert the part to a percentage: 5÷20×100%=25%."},{"question":"What percentage is 10 of 40 learners?","options":[{"id":"A","text":"35%"},{"id":"B","text":"45%"},{"id":"C","text":"25%"},{"id":"D","text":"12.5%"}],"answer":"C","explanation":"Convert the part to a percentage: 10÷40×100%=25%."},{"question":"What percentage is 15 of 60 learners?","options":[{"id":"A","text":"35%"},{"id":"B","text":"45%"},{"id":"C","text":"12.5%"},{"id":"D","text":"25%"}],"answer":"D","explanation":"Convert the part to a percentage: 15÷60×100%=25%."},{"question":"What percentage is 8 of 40 learners?","options":[{"id":"A","text":"20%"},{"id":"B","text":"30%"},{"id":"C","text":"40%"},{"id":"D","text":"10%"}],"answer":"A","explanation":"Convert the part to a percentage: 8÷40×100%=20%."},{"question":"What percentage is 12 of 30 learners?","options":[{"id":"A","text":"50%"},{"id":"B","text":"40%"},{"id":"C","text":"60%"},{"id":"D","text":"20%"}],"answer":"B","explanation":"Convert the part to a percentage: 12÷30×100%=40%."},{"question":"What percentage is 9 of 30 learners?","options":[{"id":"A","text":"40%"},{"id":"B","text":"50%"},{"id":"C","text":"30%"},{"id":"D","text":"15%"}],"answer":"C","explanation":"Convert the part to a percentage: 9÷30×100%=30%."},{"question":"Two pie-chart sectors are 120° and 90°. Find the third sector angle.","options":[{"id":"A","text":"165°"},{"id":"B","text":"180°"},{"id":"C","text":"75°"},{"id":"D","text":"150°"}],"answer":"D","explanation":"A full pie has 360°. Remaining sector=360−120−90=150°."},{"question":"Two pie-chart sectors are 180° and 90°. Find the third sector angle.","options":[{"id":"A","text":"90°"},{"id":"B","text":"105°"},{"id":"C","text":"120°"},{"id":"D","text":"45°"}],"answer":"A","explanation":"A full pie has 360°. Remaining sector=360−180−90=90°."},{"question":"Two pie-chart sectors are 150° and 120°. Find the third sector angle.","options":[{"id":"A","text":"105°"},{"id":"B","text":"90°"},{"id":"C","text":"120°"},{"id":"D","text":"45°"}],"answer":"B","explanation":"A full pie has 360°. Remaining sector=360−150−120=90°."},{"question":"Two pie-chart sectors are 120° and 60°. Find the third sector angle.","options":[{"id":"A","text":"195°"},{"id":"B","text":"210°"},{"id":"C","text":"180°"},{"id":"D","text":"90°"}],"answer":"C","explanation":"A full pie has 360°. Remaining sector=360−120−60=180°."},{"question":"Two pie-chart sectors are 90° and 60°. Find the third sector angle.","options":[{"id":"A","text":"225°"},{"id":"B","text":"240°"},{"id":"C","text":"105°"},{"id":"D","text":"210°"}],"answer":"D","explanation":"A full pie has 360°. Remaining sector=360−90−60=210°."},{"question":"For categories on a bar chart, the vertical axis should use:","options":[{"id":"A","text":"One consistent frequency scale"},{"id":"B","text":"A different scale for each category"},{"id":"C","text":"Only decorative colours"},{"id":"D","text":"No numeric labels"}],"answer":"A","explanation":"A consistent labelled axis permits fair comparison of category frequencies."}]}]'::jsonb) AS x(seq int,code text,slug text,name text,body text,points jsonb,cards jsonb,questions jsonb);
DO $do$ BEGIN IF (SELECT count(*) FROM public.courses WHERE id IN ('e670d71b-47de-4531-b353-7c1d914f796d','e8b6c4d7-ddc1-45f5-9d44-f18470942726') AND status='published' AND subject_id='f96346aa-0aba-442a-b9ea-2658c17ebef9' AND term_id='44ccb915-f4f1-4600-96f6-810c51dc4071') <> 2 THEN RAISE EXCEPTION 'Target JSS2 classes changed'; END IF; END $do$;
INSERT INTO public.topics(id,subject_id,class_id,term_id,name,code,description,learning_objectives,order_index,estimated_hours,is_active,created_at,updated_at)
SELECT gen_random_uuid(),c.subject_id,c.class_id,c.term_id,u.name,u.code,'Original NERDC-aligned topic: '||u.name,
 to_jsonb(ARRAY['Explain the topic using accurate subject vocabulary','Solve worked examples and verify the method','Complete original practice independently']),u.seq+1,1,true,now(),now()
FROM public.courses c CROSS JOIN guide_units u
WHERE c.id IN ('e670d71b-47de-4531-b353-7c1d914f796d','e8b6c4d7-ddc1-45f5-9d44-f18470942726') AND NOT EXISTS (SELECT 1 FROM public.topics t WHERE t.class_id=c.class_id AND t.subject_id=c.subject_id AND t.term_id=c.term_id AND lower(trim(t.name))=lower(trim(u.name)))
ON CONFLICT (subject_id,class_id,term_id,code) DO NOTHING;
INSERT INTO public.lessons(id,course_id,section_id,topic_id,title,slug,description,learning_objectives,content_type,written_content,key_points,order_index,is_free,is_published,estimated_minutes,teaching_version,content_quality,created_at,updated_at)
SELECT gen_random_uuid(),c.id,(SELECT cs.id FROM public.course_sections cs WHERE cs.course_id=c.id AND cs.is_active ORDER BY (cs.title='Third Term Lessons') DESC,cs.order_index LIMIT 1),
t.id,'JSS2 Mathematics: '||u.name,u.slug,
'Original fully explained curriculum lesson with examples and independent practice',
to_jsonb(ARRAY['Understand the principle','Work through an example','Apply the method independently']),'text',u.body,u.points,
coalesce((SELECT max(l.order_index) FROM public.lessons l WHERE l.course_id=c.id),0)+u.seq,true,true,30,2,'ready',now(),now()
FROM public.courses c CROSS JOIN guide_units u JOIN public.topics t ON t.class_id=c.class_id AND t.subject_id=c.subject_id AND t.term_id=c.term_id AND lower(trim(t.name))=lower(trim(u.name))
WHERE c.id IN ('e670d71b-47de-4531-b353-7c1d914f796d','e8b6c4d7-ddc1-45f5-9d44-f18470942726') AND NOT EXISTS (SELECT 1 FROM public.lessons l WHERE l.course_id=c.id AND (l.slug=u.slug OR l.topic_id=t.id))
ON CONFLICT(course_id,slug) DO NOTHING;
INSERT INTO public.flashcards(id,course_id,lesson_id,topic_id,subject_id,title,description,cards,mode,is_public,created_at,updated_at)
SELECT gen_random_uuid(),l.course_id,l.id,l.topic_id,c.subject_id,'JSS2 '||u.name||' — recall','Concept-based original cards',u.cards,'curriculum-prebuilt',true,now(),now()
FROM guide_units u JOIN public.lessons l ON l.slug=u.slug AND l.is_published=true JOIN public.courses c ON c.id=l.course_id
WHERE c.id IN ('e670d71b-47de-4531-b353-7c1d914f796d','e8b6c4d7-ddc1-45f5-9d44-f18470942726') AND NOT EXISTS (SELECT 1 FROM public.flashcards f WHERE f.lesson_id=l.id AND f.is_public AND f.created_by IS NULL AND f.mode='curriculum-prebuilt')
ON CONFLICT DO NOTHING;
INSERT INTO public.questions(id,subject_id,topic_id,class_id,question_type,question_text,options,correct_answer,explanation,difficulty,marks,source,exam_name,tags,is_active,created_at,updated_at)
SELECT gen_random_uuid(),c.subject_id,l.topic_id,c.class_id,'mcq',q->>'question',q->'options',to_jsonb(q->>'answer'),q->>'explanation',
'medium',1,'THE GUIDE Original Worked Practice','JSS2 Third Term Original Mathematics Practice',
jsonb_build_array('original-curriculum','jss2-third-term','lesson:'||l.id::text),true,now(),now()
FROM guide_units u JOIN public.lessons l ON l.slug=u.slug AND l.is_published=true JOIN public.courses c ON c.id=l.course_id CROSS JOIN LATERAL jsonb_array_elements(u.questions) q
WHERE c.id IN ('e670d71b-47de-4531-b353-7c1d914f796d','e8b6c4d7-ddc1-45f5-9d44-f18470942726') AND jsonb_array_length(q->'options')=4
AND NOT EXISTS (SELECT 1 FROM public.questions old WHERE old.topic_id=l.topic_id AND old.question_text=q->>'question' AND old.source='THE GUIDE Original Worked Practice');
UPDATE public.courses c SET lesson_count=(SELECT count(*) FROM public.lessons l WHERE l.course_id=c.id AND l.is_published=true),updated_at=now() WHERE c.id IN ('e670d71b-47de-4531-b353-7c1d914f796d','e8b6c4d7-ddc1-45f5-9d44-f18470942726');
DROP TABLE guide_units;
COMMIT;